import{z as i,x as n,o as r,c as M,q as B,j as A,D as E,d as e,s as t,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Moore 与 Mealy","description":"","frontmatter":{"title":"Moore 与 Mealy","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/moore-mealy.md","filePath":"cs/moore-mealy.md","lastUpdated":1791413859000}'),d={name:"cs/moore-mealy.md"};function m(p,a,c,h,y,F){const l=n("Mermaid");return r(),M("div",null,[a[2]||(a[2]=B('<h1 id="moore-与-mealy" tabindex="-1">Moore 与 Mealy <a class="header-anchor" href="#moore-与-mealy" aria-label="Permalink to &quot;Moore 与 Mealy&quot;">​</a></h1><div class="epigraph"><p>输出只看现态，则毛刺少、往往晚一拍；输出还看输入，则组合路径穿过控制器，可能更快也更险。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/fsm-control">有限状态机</a>已经写出 \\(\\delta\\) 与 \\(\\lambda\\)，并点了 Moore/Mealy 的差别。本课不重列编码，也不从正则语言另起。缺口是把两种输出接到<strong>关键路径与毛刺</strong>上：后课 CPU 控制器、总线应答，必须选哪一种，不能停在「两种都承认」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Moore：\\(\\lambda:S\\to\\) 输出，输出随状态寄存器，边沿后才变。Mealy：\\(\\lambda:S\\times\\Sigma\\to\\) 输出，输入一变输出就可以变，不必等下一拍。缺口是时序：Mealy 把输入到输出的组合算进<a href="/cs/critical-path">关键路径</a>，并可能把输入毛刺送到输出；Moore 多一拍延迟，输出在周期内稳定（除边沿附近）。</p><p><span class="marginnote">用序列检测「1011」数延迟：输入的最后一个 1 到达的那一拍，Mealy 当拍就能拉高匹配输出；改成 Moore 则必须先转移到「匹配」状态，输出要等到下一个时钟沿才出现——整整晚一拍，这就是「快」与「稳」交换的具体单位。</span></p><p>混合常见：若干位 Moore（使能、选通），若干位 Mealy（提前应答）。本课钉分类，不把状态最小化算法写完。</p><h3 id="mealy-不是「更高级的-fsm」" tabindex="-1">Mealy 不是「更高级的 FSM」 <a class="header-anchor" href="#mealy-不是「更高级的-fsm」" aria-label="Permalink to &quot;Mealy 不是「更高级的 FSM」&quot;">​</a></h3><p>不是表达能力分层。任何 Mealy 可改造成 Moore（加状态、加一拍）。把 Mealy 当更现代，后课会把所有控制做成输入组合，保持时间更容易坏。</p><p><span class="marginnote">Harris 用序列检测对比：Mealy 可在输入到达当拍出「已匹配」。CPU 的 MemRead 等常同步到状态，避免组合读脉冲切到存储器中途。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>同一规格画两张图：Moore 把输出标在圈上，Mealy 标在边上。综合：Moore 输出只接现态译码；Mealy 再与输入门。检查：Mealy 输出是否满足下游建立；是否允许毛刺（纯组合下游 vs 边沿采样）。</p>',12)),(r(),A(s,null,{default:E(()=>[t(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E7%8E%B0%E6%80%81%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20MOORE%5B%22Moore%EF%BC%9A%E8%BE%93%E5%87%BA%E5%8F%AA%E7%9C%8B%E7%8A%B6%E6%80%81%22%5D%0A%20%20ST%20--%3E%20MEALY%5B%22Mealy%EF%BC%9A%E8%BE%93%E5%87%BA%E7%9C%8B%E7%8A%B6%E6%80%81%E4%B8%8E%E8%BE%93%E5%85%A5%22%5D%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20MEALY%0A%20%20MEALY%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%AE%A1%E6%95%B0%E5%99%A8%E7%89%B9%E4%BE%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("后课多周期控制器：多数拍内控制向量跟状态走（Moore），个别「输入已就绪则当拍转」用 Mealy。计数器输出就是状态本身，是 Moore 的特例。"),o("a",{href:"/cs/setup-hold"},"建立保持"),e("对 Mealy 输出到下游 FF 仍然适用。")],-1)),(r(),A(s,null,{default:E(()=>[t(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20GL%5B%22%E8%BE%93%E5%85%A5%E6%AF%9B%E5%88%BA%3A%20%E7%BB%84%E5%90%88%E9%80%BB%E8%BE%91%E6%8A%96%E5%8A%A8%22%5D%20--%3E%20Q%7B%22%E8%BE%93%E5%87%BA%E5%93%AA%E7%A7%8D%3F%22%7D%0A%20%20Q%20--%3E%7C%22Mealy%22%7C%20M1%5B%22%E6%AF%9B%E5%88%BA%E5%BD%93%E6%8B%8D%E7%A9%BF%E8%BF%87%E8%BE%93%E5%87%BA%E9%97%A8%22%5D%0A%20%20M1%20--%3E%20M2%5B%22%E4%B8%8B%E6%B8%B8%E8%8B%A5%E7%BA%AF%E7%BB%84%E5%90%88%3A%20%E6%AF%9B%E5%88%BA%E5%A4%96%E9%9C%B2%22%5D%0A%20%20M2%20--%3E%20M3%5B%22%E4%B8%8B%E6%B8%B8%E8%8B%A5%E8%BE%B9%E6%B2%BF%E9%87%87%E6%A0%B7%3A%20%E5%BB%BA%E7%AB%8B%E7%AA%97%E5%8F%A3%E8%A2%AB%E8%B5%8C%22%5D%0A%20%20Q%20--%3E%7C%22Moore%22%7C%20O1%5B%22%E6%AF%9B%E5%88%BA%E5%85%88%E5%88%B0%E7%8A%B6%E6%80%81%E5%AF%84%E5%AD%98%E5%99%A8%E8%BE%93%E5%85%A5%22%5D%0A%20%20O1%20--%3E%20O2%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%8F%AA%E5%9C%A8%E6%97%B6%E9%92%9F%E6%B2%BF%E9%87%87%E6%A0%B7%22%5D%0A%20%20O2%20--%3E%20O3%5B%22%E6%AF%9B%E5%88%BA%E8%90%BD%E5%9C%A8%E6%B2%BF%E5%A4%96%E5%B0%B1%E8%A2%AB%E6%8C%A1%E6%8E%89%22%5D%0A%20%20O3%20--%3E%20O4%5B%22%E8%BE%93%E5%87%BA%E5%91%A8%E6%9C%9F%E5%86%85%E7%A8%B3%E5%AE%9A%2C%20%E5%8F%AA%E5%9C%A8%E6%B2%BF%E5%90%8E%E5%8F%98%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">毛刺（glitch）就是输入还在稳定过程中，组合逻辑在最终值之前短暂输出错误值的抖动——不是 bug，是信号路径长短不一的必然产物。Moore 的状态寄存器像一道闸门，只有时钟沿那一瞬开门，抖动恰好落在沿之外就进不来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证两种自动机的形式等价细节，不引入层次状态机、UML。异步 Mealy（无时钟）不在主干。</p><p><span class="marginnote">初学者容易以为选 Moore 还是 Mealy 只是画风偏好。实际上这一选直接决定下游电路的时序合同：Mealy 的输出线要满足建立/保持余量，毛刺能不能容忍要看下游是边沿采样还是纯组合——画 FSM 图的那一刻，关键路径就已经被画进去了。</span></p><p>后课默认：控制器先按 Moore 画稳，需要当拍响应再局部 Mealy；计数器沿环走，输出即现态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Moore 输出随状态，稳、常晚一拍。</li><li>Mealy 输出含输入，快、进关键路径、易毛刺。</li><li>表达力可互化；选型是时序与延迟。</li><li>出处：Harris and Harris。</li></ul>',7))])}const D=i(d,[["render",m]]);export{u as __pageData,D as default};
